INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Einrichtung IT-Arbeitsplätze > IT-Sicherheit > Informationsschutz & Datenschutz
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Einrichtung von IT-Arbeitsplätzen Datenschutzvorschriften wie die DSGVO beachtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Anforderungen sind bindend"}, {"text": "Nein", "correct": false, "because": "Pflicht zur Einhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Arbeitsplätze ohne Sicherheitsmaßnahmen zum Informationsschutz betrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Schutz sensibler Daten ist erforderlich"}, {"text": "Ja", "correct": false, "because": "Risiko von Datenverlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Verschlüsselung von Daten bei der Einrichtung von IT-Arbeitsplätzen gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Empfohlen, aber nicht immer Pflicht"}, {"text": "Ja", "correct": false, "because": "Abhängig von Datenart"}]'),
('00000000-0000-0000-0000-000000000000', 'Können personenbezogene Daten ohne Zustimmung der Betroffenen verarbeitet werden?', 2, '[{"text": "Nein", "correct": true, "because": "DSGVO verlangt Einwilligung"}, {"text": "Ja", "correct": false, "because": "Einwilligung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Datenschutz bei IT-Arbeitsplätzen nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Unternehmen"}, {"text": "Ja", "correct": false, "because": "Universelle Pflicht"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist beim Informationsschutz an IT-Arbeitsplätzen am wichtigsten?', 3, '[{"text": "Datensicherheit", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Ästhetisch, nicht sicherheitsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme schützt personenbezogene Daten gemäß DSGVO?', 2, '[{"text": "Verschlüsselung", "correct": true, "because": "Sichert Datenintegrität"}, {"text": "Öffentliche Freigabe", "correct": false, "because": "Verletzt Datenschutz"}, {"text": "Papierarchivierung", "correct": false, "because": "Weniger sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage regelt den Datenschutz in der EU?', 2, '[{"text": "DSGVO", "correct": true, "because": "Datenschutz-Grundverordnung"}, {"text": "Arbeitsschutzgesetz", "correct": false, "because": "Für Sicherheit"}, {"text": "Kreislaufwirtschaftsgesetz", "correct": false, "because": "Für Abfall"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für den Informationsschutz an IT-Arbeitsplätzen eingesetzt?', 3, '[{"text": "Firewall", "correct": true, "because": "Schützt vor Netzwerkangriffen"}, {"text": "Texteditor", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "Browser", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel des Datenschutzes an IT-Arbeitsplätzen?', 2, '[{"text": "Schutz sensibler Daten", "correct": true, "because": "Verhindert Missbrauch"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Installation", "correct": false, "because": "Unabhängig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern den Informationsschutz an IT-Arbeitsplätzen?', 4, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "Firewalls", "correct": true, "because": "Blockiert Angriffe"}, {"text": "Regelmäßige Updates", "correct": true, "because": "Schließt Sicherheitslücken"}, {"text": "Öffentliches WLAN", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorschriften regeln den Datenschutz an IT-Arbeitsplätzen?', 3, '[{"text": "DSGVO", "correct": true, "because": "EU-weite Regelung"}, {"text": "BDSG", "correct": true, "because": "Bundesdatenschutzgesetz"}, {"text": "IT-Sicherheitsgesetz", "correct": true, "because": "Sicherheitsanforderungen"}, {"text": "Arbeitsschutzgesetz", "correct": false, "because": "Für Sicherheit, nicht Datenschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken bestehen ohne Informationsschutz?', 3, '[{"text": "Datenverlust", "correct": true, "because": "Durch Angriffe"}, {"text": "Rechtsverstöße", "correct": true, "because": "Verletzung der DSGVO"}, {"text": "Reputationsschaden", "correct": true, "because": "Vertrauensverlust"}, {"text": "Geringe Lautstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für den Datenschutz an IT-Arbeitsplätzen wichtig?', 4, '[{"text": "Zugriffskontrollen", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "Datensicherung", "correct": true, "because": "Verhindert Verlust"}, {"text": "Schulung der Mitarbeiter", "correct": true, "because": "Sensibilisiert für Risiken"}, {"text": "Monitorgröße", "correct": false, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein guter Informationsschutz?', 3, '[{"text": "Rechtssicherheit", "correct": true, "because": "Erfüllt Gesetze"}, {"text": "Datensicherheit", "correct": true, "because": "Schützt Informationen"}, {"text": "Vertrauen der Nutzer", "correct": true, "because": "Stärkt Reputation"}, {"text": "Geringere Hardwarekosten", "correct": false, "because": "Nicht primär"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die DSGVO verlangt Schutzmaßnahmen für personenbezogene Daten. b) Informationsschutz ist nur für große Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO ja, Schutz für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verschlüsselung schützt Daten an IT-Arbeitsplätzen. b) Eine Firewall ist für den Datenschutz unnötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ja, Firewall wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zugriffskontrollen sind Teil des Informationsschutzes. b) Die DSGVO erlaubt Datenverarbeitung ohne Zustimmung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zugriff ja, Zustimmung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Regelmäßige Updates erhöhen die IT-Sicherheit. b) Datenschutz betrifft nur personenbezogene Daten.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Updates ja, DSGVO auf Personen bezogen"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schulung der Mitarbeiter fördert den Datenschutz. b) IT-Arbeitsplätze sind ohne Sicherheitsmaßnahmen gesetzeskonform.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schulung ja, Maßnahmen nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

